usage:
import { EnvVars } from "@/components/design-for-ai/devtools-env-vars";

<EnvVars
  project="ledgerline"
  environment="production"
  variables={variables} // { key, sensitive, updated, scopes, values }[]
  onChange={(next) => save(next)}
  onRedeploy={(env) => redeploy(env)}
/>

// Secrets stay masked until revealed. Import parses a .env paste and skips duplicates.
// A redeploy banner appears after a scope change or a successful import.
